style.css:
/* Falling Stars Overlay */
body::after {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    background: url("https://files.catbox.moe/erjzd7.gif") no-repeat center center fixed;
    background-size: cover;
    z-index: 9999;
}

/* Blood Overlay */
body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    background: url("https://files.catbox.moe/cqg8p1.gif") no-repeat top center fixed;
    background-size: contain;
    z-index: 9999;
}
